 // optionally 'e' or 'E', an optional '+' or '-', and one or more digits. No
 // spaces, no '+' sign on the mantissa, no inf/nan/hex. Every value must be
 // bit-identical to std::strtod (correctly rounded, round-half-to-even).
+// Fast path for integers, short decimals, and scientific notation with up to 15
+// significant digits and |combined exponent| <= 22 (Clinger's exact range).
+static inline bool is_digit(char c) { return c >= '0' && c <= '9'; }
+
+// Exact powers of ten for scaling (0..22).
+static const double pow10_table[23] = {
+    1e0, 1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7,
+    1e8, 1e9, 1e10, 1e11, 1e12, 1e13, 1e14, 1e15,
+    1e16, 1e17, 1e18, 1e19, 1e20, 1e21, 1e22
+};
+
 extern "C" size_t parse_doubles(const char* buf, size_t len, double* out) {
     const char* p = buf;
     const char* end = buf + len;
     size_t count = 0;
     while (p < end) {
+        // Fast path for integers, short decimals, and scientific notation.
+        const char* q = p;
+        bool neg = false;
+        if (*q == '-') { neg = true; ++q; }
+        if (!is_digit(*q)) goto fallback;
+
+        uint64_t mantissa = 0;
+        int digits = 0;       // total significant digits parsed
+        int exp10 = 0;        // decimal exponent adjustment
+
+        // Parse integer part
+        while (is_digit(*q)) {
+            if (digits < 15) {
+                mantissa = mantissa * 10 + (*q - '0');
+            }
+            ++digits;
+            ++q;
+        }
+
+        // Optional fractional part
+        if (*q == '.') {
+            ++q;
+            if (!is_digit(*q)) goto fallback;  // must have at least one digit after '.'
+            while (is_digit(*q)) {
+                if (digits < 15) {
+                    mantissa = mantissa * 10 + (*q - '0');
+                    --exp10;  // each fractional digit reduces the exponent
+                }
+                ++digits;
+                ++q;
+            }
+        }
+
+        // Optional exponent part
+        if (*q == 'e' || *q == 'E') {
+            ++q;
+            bool exp_neg = false;
+            if (*q == '+' || *q == '-') {
+                exp_neg = (*q == '-');
+                ++q;
+            }
+            if (!is_digit(*q)) goto fallback;
+            int exp_val = 0;
+            while (is_digit(*q)) {
+                exp_val = exp_val * 10 + (*q - '0');
+                if (exp_val > 100) goto fallback;  // prevent overflow
+                ++q;
+            }
+            if (exp_neg) exp_val = -exp_val;
+            exp10 += exp_val;
+        }
+
+        // Must end with newline
+        if (*q != '\n') goto fallback;
+
+        // Only handle up to 15 significant digits for exact conversion
+        if (digits <= 15) {
+            double d = (double)mantissa;
+            // Clinger's fast path: mantissa < 2^53 and |exp10| <= 22
+            if (mantissa < 9007199254740992ULL && exp10 >= -22 && exp10 <= 22) {
+                if (exp10 < 0) {
+                    d /= pow10_table[-exp10];
+                } else if (exp10 > 0) {
+                    d *= pow10_table[exp10];
+                }
+                out[count++] = neg ? -d : d;
+                p = q + 1; // skip '\n'
+                continue;
+            }
+        }
+
+    fallback:
         char* next;
         out[count++] = std::strtod(p, &next);
         p = next;
